## 7. `internal/router/routes.go`

```go
package router

import (
	"net/http"

	"apiv1/handler"
)

// Static routes use explicit HTTP methods for maximum compatibility.
// Parametric routes use a regex that extracts the numeric/ID portion.
var (
	getByIDRoute   = "GET " + userPathParam
	updateRoute    = "POST " + userPathParam
	catchAllRoute  = "/*"
)

const userPathParam = `^/users/[^/]+$`

// Init registers every route on the supplied ServeMux.
func Init(m *http.ServeMux) {
	m.HandleFunc("GET /health",             handler.HealthHandler)
	m.HandleFunc("GET /users",              handler.ListUsersHandler)
	m.HandleFunc("POST /users",             handler.CreateUserHandler)
	m.HandleFunc(getByIDRoute,             handler.GetUserByIDHandler)
	m.HandleFunc(updateRoute,              handler.UpdateUserHandler)
	m.HandleFunc(catchAllRoute,            handleNotFound)
}

func handleNotFound(w http.ResponseWriter, r *http.Request) {
	http.NotFound(w, r)
}
```

