## Running & testing

```bash
# Start the server (defaults to :8080; use PORT=3000 env var)
go run ./cmd/apiv1

# Health check
curl -s http://localhost:8080/health | jq .

# List users
curl -s 'http://localhost:8080/users?limit=3&offset=0&q=user' | jq .

# Create a user
curl -s -X POST http://localhost:8080/users \
  -H 'Content-Type: application/json' \
  -d '{"name":"Ada Lovelace","email":"ada@example.com","role":"admin"}' \
  | jq .
# ← 201, includes "Location: /users/7k9…j2a"

# Update a user (partial)
id=$(curl -s -G 'http://localhost:8080/users' \
  -d 'query=' \
  | grep -oP 'location:\s*/users/\K[^ ]+' ; # or fetch from a previous response)
curl -s -X POST "http://localhost:8080/users/$id" \
  -H 'Content-Type: application/json' \
  -d '{"name":"Ada H. Lovelace"}' | jq .

# 404 example
curl -s -o /dev/null -w "%{http_code}" http://localhost:8080/users/nonexistent

# CORS preflight
curl -s -X OPTIONS \
  -H 'Origin: https://myapp.com' \
  -H 'Access-Control-Request-Method: POST' \
